def get_ports(self):

    out = self._cli_run(['showport'])




    out = out[1:len(out) - 2]

    ports = {'FC': [], 'iSCSI': {}}
    for line in out:
        tmp = line.split(',')

        if tmp:
            if tmp[1] == 'target' and tmp[2] == 'ready':
                if tmp[6] == 'FC':
                    ports['FC'].append(tmp[4])


    out = self._cli_run(['showport', '-iscsi'])




    out = out[1:len(out) - 2]
    for line in out:
        tmp = line.split(',')

        if tmp and len(tmp) > 2:
            if tmp[1] == 'ready':
                ports['iSCSI'][tmp[2]] = {}


    result = self._cli_run(['showport', '-iscsiname'])
    if result:


        result = result[1:]
        for line in result:
            info = line.split(",")
            if info and len(info) > 2:
                if info[1] in ports['iSCSI']:
                    nsp = info[0]
                    ip_addr = info[1]
                    iqn = info[2]
                    ports['iSCSI'][ip_addr] = {'nsp': nsp,
                                               'iqn': iqn
                                               }

    LOG.debug("PORTS = %s" % pprint.pformat(ports))
    return ports

